using System.Collections;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;
namespace PontoCego.Tests
{
    public sealed class Polish021SceneTests
    {
        [UnitySetUp]public IEnumerator Setup(){GameSession.ExploreNeighborhood("01_Riberal");yield return null;yield return null;}
        [UnityTest]public IEnumerator RescuedAdryanUsesChildFrames(){var mission=WorldHub.Instance.Find("21_Adryan");var sequence=mission.actors.GetComponentsInChildren<GameplaySequence>(true).First(x=>x.actor&&x.actor.name.StartsWith("Adryan"));var anim=sequence.actor.GetComponent<ReferenceActorAnimation>();Assert.That(anim,Is.Not.Null);Assert.That(anim.idle.Length,Is.EqualTo(8));Assert.That(anim.walk.Length,Is.EqualTo(24));foreach(var sprite in anim.idle){Assert.That(sprite.name,Does.StartWith("Adryan criança"));Assert.That(sprite.bounds.size.y,Is.InRange(.9f,1.6f));}yield return null;}
        [UnityTest]public IEnumerator CommonEnemiesHaveSixLooksAndFoodButBossesDoNot(){var actors=WorldHub.Instance.missions.SelectMany(x=>x.actors.GetComponentsInChildren<EnemyAgent>(true)).ToArray();Assert.That(actors.Where(e=>e.GetComponent<EnemyVariety>()).Select(e=>e.GetComponent<EnemyVariety>().archetype).Distinct().Count(),Is.EqualTo(6));foreach(var enemy in actors){if(enemy.GetComponent<Health>().boss){Assert.That(enemy.GetComponent<CommonEnemyFoodDrop>(),Is.Null);continue;}Assert.That(enemy.GetComponent<CommonEnemyFoodDrop>(),Is.Not.Null);Assert.That(enemy.poses[0].name,Does.StartWith("Variedade inimiga"));}yield return null;}
        [UnityTest]public IEnumerator DoorsAreOpenAndWallsRemainSolid(){Physics2D.SyncTransforms();var contracts=Object.FindObjectsByType<SceneryFootprint2D>();Assert.That(contracts.Length,Is.GreaterThan(150));foreach(var contract in contracts){var boxes=contract.GetComponentsInChildren<BoxCollider2D>();Assert.That(boxes.Length,Is.GreaterThanOrEqualTo(4));foreach(var gate in contract.entrances){foreach(var box in boxes)Assert.That(box.OverlapPoint(gate),Is.False,"Closed doorway: "+contract.transform.parent.name);var overlaps=Physics2D.OverlapCircleAll(gate,.25f,LayerMask.GetMask("World"));Assert.That(overlaps.Any(c=>c.GetComponentInParent<SceneryFootprint2D>()==contract),Is.False,"Not enough foot clearance");}var r=contract.groundBounds;Assert.That(boxes.Any(b=>b.OverlapPoint(new Vector2(r.center.x,r.yMax))),Is.True,"Missing rear wall");}yield return null;}
        [UnityTest]public IEnumerator HenzoStaminaUpgradePersistsInSessionWithoutChangingLife(){var shop=Object.FindAnyObjectByType<EquipmentShop>();var player=Object.FindAnyObjectByType<PlayerMotor>();var hp=player.GetComponent<Health>();float life=hp.maximum,capacity=player.Model.StaminaCapacity;var save=GameSession.Current;save.currency=10000;for(int i=0;i<5;i++)shop.Buy(10);Assert.That(save.staminaLevel,Is.EqualTo(5));Assert.That(player.Model.StaminaCapacity,Is.EqualTo(capacity*2).Within(.01f));Assert.That(hp.maximum,Is.EqualTo(life));int money=save.currency;shop.Buy(10);Assert.That(save.currency,Is.EqualTo(money));Assert.That(Resources.Load<Sprite>("henzo-stamina-white-v1"),Is.Not.Null);yield return null;}
        [UnityTest]public IEnumerator BirdSourcesAreMutedAndFootstepsHaveNoClip(){yield return null;var ambience=Object.FindAnyObjectByType<WorldAmbience2D>();Assert.That(ambience.DaySource.mute,Is.True);Assert.That(Resources.FindObjectsOfTypeAll<AudioClip>().Any(c=>c.name=="shoe"),Is.False);}
        [UnityTest]public IEnumerator MateusTasksHaveDifferentActions(){var go=new GameObject("Quest semantics test");var task=go.AddComponent<GoldenQuestPickup>();task.chain=0;task.step=1;Assert.That(task.Kind,Is.EqualTo(GoldenTaskKind.Photograph));task.step=2;Assert.That(task.Kind,Is.EqualTo(GoldenTaskKind.Recover));task.chain=1;task.step=1;Assert.That(task.Kind,Is.EqualTo(GoldenTaskKind.Repair));task.step=2;Assert.That(task.Kind,Is.EqualTo(GoldenTaskKind.Deliver));Object.Destroy(go);yield return null;}
        [UnityTest]public IEnumerator PrimaryObjectiveIsAvailableToHud(){var hud=Object.FindAnyObjectByType<GameHud>();yield return null;Assert.That(hud.MissionObjective,Is.Not.Empty);Assert.That(Object.FindAnyObjectByType<PlayerMotor>().GetComponent<ReferenceActorAnimation>().run.Length,Is.GreaterThanOrEqualTo(16));}
    }
}
